public static int length(Node<Integer> first) {
    int count = 0;
    Node<Integer> p = first;
    while (p != null) {
        count++;
        p = p.getNext();
    }
    return count;
}

public static int sum(Node<Integer> first) {
    int sum = 0;
    Node<Integer> p = first;
    while (p != null) {
        sum = sum + p.getValue();
        p = p.getNext();
    }
    return sum;
}

exercise.mainCode:
Node<Integer> first = new Node<Integer>(6, new Node<Integer>(2, new Node<Integer>(9, new Node<Integer>(3))));
System.out.println("סעיף א: " + length(first));
System.out.println("סעיף ב: " + sum(first));

